KG42.register("rules-0e30436c0705c29a2a493531",{"id":"36-dsm_mechanism_design::v141-c-R001","paper":"36-dsm_mechanism_design","record":{"rule_id":"v141-c-R001","mechanism_id":"v141-a-M01","name":"Demand submission","process_stage":"bidding","market_meaning":"The VCG payment construction makes truthful demand declaration a dominant strategy for each user, regardless of other users’ strategies. Scope: User demand declarations in the proposed VCG demand-side management mechanism. Condition: Electricity payment values are selected using the VCG mechanism defined in (21) and (22). Each user is required to submit energy-demand information, including its feasible power-consumption set, to the energy provider. Scope: User declarations in the proposed VCG demand-side management mechanism.","independence_rationale":"Relations governed by the approved function bidding.demand under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","settlement.payment"],"E":[{"edge_id":"v141-c-R001-E001","source":"settlement.payment","target":"bidding.demand","type":"implies","constraint_ids":["v141-c-R001-C001"],"evidence_ids":["v141-b-g02-e019","v141-b-g02-e020"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"User declarations in the proposed VCG demand-side management mechanism. | User demand declarations in the proposed VCG demand-side management mechanism.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E05","v141-b-g01-E29","v141-b-g02-e019","v141-b-g02-e020"]},"x":[{"variable_id":"v141-c-R001-X001","symbol":"\\hat{\\mathbf I}_n","meaning":"User n's declared demand-information tuple: declared utility parameter, declared per-slot maximum/minimum power levels, and declared minimum total energy requirement; the declaration action at the bidding stage.","kind":"operational","domain":"Declared counterpart of the true information set (15): \\hat{\\mathbf I}_n = \\{\\hat\\omega_n,\\hat{\\mathbf M}_n,\\hat{\\mathbf m}_n,\\hat E_n\\}; source gives component meanings, not separate numeric domains in the supplied evidence.","unit":null,"indices":["n"],"evidence_ids":["v141-b-g01-E29","v141-b-g02-e013","v141-b-g03-e01-vcg-declaration"]}],"theta":[{"parameter_id":"v141-c-R001-T001","symbol":"\\mathbf I_n","meaning":"True private demand-information tuple of user n: utility parameter \\omega_n, per-slot maximum and minimum power levels \\mathbf M_n,\\mathbf m_n, and minimum total energy requirement E_n (15); fixed from the mechanism's perspective.","value":{"kind":"symbolic","number_value":null,"text_value":"\\{\\omega_n,\\mathbf M_n,\\mathbf m_n,E_n\\}"},"unit":null,"indices":["n"],"evidence_ids":["v141-b-g01-E29","v141-b-g02-e013","v141-b-g02-e014"]}],"phi":[{"constraint_id":"v141-c-R001-C001","kind":"logical","role":"core","statement":"The VCG payment construction makes truthful demand declaration a dominant strategy for each user, regardless of other users’ strategies. Scope: User demand declarations in the proposed VCG demand-side management mechanism. Condition: Electricity payment values are selected using the VCG mechanism defined in (21) and (22).","expression":"\\forall n\\in\\mathcal N,\\ \\forall \\hat{\\mathbf I}_{-n},\\ \\forall \\tilde{\\mathbf I}_n:\\quad U_n\\!\\left(\\sum_{k\\in\\mathcal K}x_n^k(\\mathbf I_n,\\hat{\\mathbf I}_{-n})\\right)-t_n(\\mathbf I_n,\\hat{\\mathbf I}_{-n})\\ge U_n\\!\\left(\\sum_{k\\in\\mathcal K}x_n^k(\\tilde{\\mathbf I}_n,\\hat{\\mathbf I}_{-n})\\right)-t_n(\\tilde{\\mathbf I}_n,\\hat{\\mathbf I}_{-n}),\\quad \\text{where }x(\\cdot),t(\\cdot)\\text{ are VCG allocation (21) and payment (22).}","formalization_origin":"equivalent_translation","template_id":null,"members":["settlement.payment","bidding.demand"],"variable_refs":["v141-c-R001-X001"],"parameter_refs":["v141-c-R001-T001"],"evidence_ids":["v141-b-g02-e017","v141-b-g02-e018","v141-b-g02-e019","v141-b-g02-e020","v141-b-g02-e029"]},{"constraint_id":"v141-c-R001-C002","kind":"procedural","role":"core","statement":"Each user is required to submit energy-demand information, including its feasible power-consumption set, to the energy provider. Scope: User declarations in the proposed VCG demand-side management mechanism.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":["v141-c-R001-X001"],"parameter_refs":[],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E05","v141-b-g01-E29"]},{"constraint_id":"v141-c-R001-C003","kind":"mathematical","role":"supporting","statement":"The declared demand information of user n is the tuple of declared utility parameter, declared per-slot maximum and minimum power levels, and declared minimum total energy requirement, as defined in (16).","expression":"\\hat{\\mathbf I}_n \\triangleq \\{\\hat\\omega_n,\\hat{\\mathbf M}_n,\\hat{\\mathbf m}_n,\\hat E_n\\}","formalization_origin":"source","template_id":null,"members":["bidding.demand"],"variable_refs":["v141-c-R001-X001"],"parameter_refs":[],"evidence_ids":["v141-b-g01-E29","v141-b-g02-e013"]}],"pi":[{"evidence_id":"v141-b-g01-E02","location":{"location_id":"src-0fb1d9d41e-p01-c1r2__v141-a-M01-bidding","page":1,"printed_page":"1170","section":"Abstract","anchor_text":"Abstract—In the future smart grid, both users and power com- ne panies can potentially beneﬁt from t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"Our design requires that each user provides some information about its energy demand. In return, the energy provider will determine each user’s electricity bill payment."},{"evidence_id":"v141-b-g01-E05","location":{"location_id":"src-0fb1d9d41e-p02-c2r2__v141-a-M01-bidding","page":2,"printed_page":"1171","section":"I. INTRODUCTION","anchor_text":"set We propose a VCG mechanism for DSM programs to en he courage efﬁcient energy consumption among u","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"In our system model, each user reveals its demand information to the energy provider."},{"evidence_id":"v141-b-g01-E29","location":{"location_id":"src-0fb1d9d41e-p05-c2r4__v141-a-M01-bidding","page":5,"printed_page":"1174","section":"III-A VCG Mechanism","anchor_text":"gy A. VCG Mechanism me In the VCG class of mechanisms, each user is asked to specify ot. its feasibl","equation_id":"(15)-(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"In the VCG class of mechanisms, each user is asked to specify its feasible set of power consumption and its utility function, which in case of the utility functions in (7) reduces to revealing a utility parameter \\omega_n. For each user n, we use U_n(\\sum_{k\\in\\mathcal{K}} x_n^k;\\omega_n) and \\hat{U}_n(\\sum_{k\\in\\mathcal{K}} x_n^k;\\hat{\\omega}_n) \\triangleq U(\\sum_{k\\in\\mathcal{K}} x_n^k;\\hat{\\omega}_n) to denote the true and declared utility function and \\mathcal{X}_n and \\hat{\\mathcal{X}}_n to denote the true and declared feasible set of power consumptions, respectively. We define \\mathbf{I}_n \\triangleq \\{\\omega_n, \\mathbf{M}_n, \\mathbf{m}_n, E_n\\} \\tag{15} and \\hat{\\mathbf{I}}_n \\triangleq \\{\\hat{\\omega}_n, \\hat{\\mathbf{M}}_n, \\hat{\\mathbf{m}}_n, \\hat{E}_n\\}. \\tag{16}"},{"evidence_id":"v141-b-g02-e019","location":{"location_id":"src-0fb1d9d41e-p06-c2r1__v141-a-M01-validation","page":6,"printed_page":null,"section":"III-A VCG Mechanism","anchor_text":"E SMART GRID USING MECHANISM DESIGN 1175 c- problem, and thus, the system objective is different fro","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"Proposition 3: If the VCG mechanism defined in (21) and (22) is used to select electricity payment values, then declaring \\(\\hat{\\mathbf I}_n=\\mathbf I_n\\) is a dominant strategy for each user \\(n\\), and following this strategy results in an efficient allocation."},{"evidence_id":"v141-b-g02-e020","location":{"location_id":"src-0fb1d9d41e-p06-c2r2__v141-a-M01-coordination","page":6,"printed_page":null,"section":"III-A VCG Mechanism","anchor_text":"this strategy results in an efﬁcient allocation. , The proof of Proposition 3 is given in Appendix A","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"First, the payment of each user is structured such that regardless of other users’ strategies, the intended user cannot do better than truthfully declaring its demand information. This feature significantly reduces the communication requirements of the method and eliminates the need for interaction among users. Second, if all users declare their demand truthfully, the proposed VCG system results in an efficient system, i.e., the utilities of all users are maximized and the cost imposed on the energy provider is minimized."},{"evidence_id":"v141-b-g02-e013","location":{"location_id":"src-0fb1d9d41e-p05-c2r4__v141-a-M01-bidding","page":5,"printed_page":null,"section":"III-A VCG Mechanism","anchor_text":"gy A. VCG Mechanism me In the VCG class of mechanisms, each user is asked to specify ot. its feasibl","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"In the VCG class of mechanisms, each user is asked to specify its feasible set of power consumption and its utility function, which in case of the utility functions in (7) reduces to revealing a utility parameter \\(\\omega_n\\). For each user \\(n\\), we use \\(U_n(\\sum_{k\\in\\mathcal K}x_n^k,\\omega_n)\\) and \\(\\hat U_n(\\sum_{k\\in\\mathcal K}x_n^k,\\hat\\omega_n)\\) to denote the true and declared utility function and \\(\\mathcal X_n\\) and \\(\\hat{\\mathcal X}_n\\) to denote the true and declared feasible set of power consumptions, respectively. We define\n\\[ \\mathbf I_n\\triangleq\\{\\omega_n,\\mathbf M_n,\\mathbf m_n,E_n\\} \\tag{15} \\]\nand\n\\[ \\hat{\\mathbf I}_n\\triangleq\\{\\hat\\omega_n,\\hat{\\mathbf M}_n,\\hat{\\mathbf m}_n,\\hat E_n\\}. \\tag{16} \\]"},{"evidence_id":"v141-b-g02-e014","location":{"location_id":"src-0fb1d9d41e-p06-c1r1__v141-a-M01-bidding","page":6,"printed_page":null,"section":"III-A VCG Mechanism","anchor_text":"SAMADI et al.: ADVANCED DEMAND SIDE MANAGEMENT FOR THE FUTURE SMART to denote the true and declared ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"to denote the true and declared demand parameters, respectively, where \\(\\hat{\\boldsymbol\\omega}\\), \\(\\hat{\\mathbf M}\\), \\(\\hat{\\mathbf m}\\), and \\(\\hat{\\mathbf E}\\) are the declared values for \\(\\boldsymbol\\omega\\), \\(\\mathbf M\\), \\(\\mathbf m\\), and \\(\\mathbf E\\), respectively. For notational simplicity, we also define\n\\[ \\mathbf I\\triangleq\\{\\boldsymbol\\omega,\\mathbf M,\\mathbf m,\\mathbf E\\} \\tag{17} \\]\nand\n\\[ \\hat{\\mathbf I}\\triangleq\\{\\hat{\\boldsymbol\\omega},\\hat{\\mathbf M},\\hat{\\mathbf m},\\hat{\\mathbf E}\\}, \\tag{18} \\]\nwhere \\(\\hat{\\boldsymbol\\omega}\\), \\(\\hat{\\mathbf M}\\), \\(\\hat{\\mathbf m}\\), and \\(\\hat{\\mathbf E}\\) are the declared values for vectors \\(\\boldsymbol\\omega\\), \\(\\mathbf M\\), \\(\\mathbf m\\), and \\(\\mathbf E\\), respectively."},{"evidence_id":"v141-b-g02-e017","location":{"location_id":"src-0fb1d9d41e-p06-c1r3__v141-a-M01-clearing","page":6,"printed_page":null,"section":"III-A VCG Mechanism","anchor_text":"sumption vectors as (21) wh and the payments are structured such that us (22) where is an arbitrary ","equation_id":"(21)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"For a given vector of declared demand information \\(\\hat{\\mathbf I}\\), the VCG mechanism chooses the energy consumption allocation \\(\\mathbf x(\\hat{\\mathbf I})\\) as an optimal solution to problem (10) and calculates optimal energy consumption vectors as\n\\[ \\mathbf x(\\hat{\\mathbf I})=\\underset{\\mathbf x_n\\in\\hat{\\mathcal X}_n,\\ n\\in\\mathcal N}{\\arg\\max}\\left\\{\\sum_{n\\in\\mathcal N}\\hat U_n\\left(\\sum_{k\\in\\mathcal K}x_n^k\\right)-\\sum_{k\\in\\mathcal K}C_k\\left(\\sum_{n\\in\\mathcal N}x_n^k\\right)\\right\\}. \\tag{21} \\]"},{"evidence_id":"v141-b-g02-e018","location":{"location_id":"src-0fb1d9d41e-p06-c1r3__v141-a-M01-pricing","page":6,"printed_page":null,"section":"III-A VCG Mechanism","anchor_text":"sumption vectors as (21) wh and the payments are structured such that us (22) where is an arbitrary ","equation_id":"(22)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"and the payments are structured such that\n\\[ t_n(\\hat{\\mathbf I})=-\\left(\\sum_{m\\in\\mathcal N_{-n}}\\hat U_m\\left(\\sum_{k\\in\\mathcal K}x_m^k\\right)-\\sum_{k\\in\\mathcal K}C_k\\left(\\sum_{m\\in\\mathcal N}x_m^k\\right)\\right)+h_n(\\hat{\\mathbf I}_{-n}), \\tag{22} \\]\nwhere \\(h_n\\) is an arbitrary function of \\(\\hat{\\mathbf I}_{-n}\\), i.e., the declared demand information of the users with user \\(n\\) excluded from the system. The true demand information of the users other than \\(n\\) is denoted by \\(\\mathbf I_{-n}\\). The definition of the payments in (22) aligns user objectives with the social planner’s objective."},{"evidence_id":"v141-b-g02-e029","location":{"location_id":"src-0fb1d9d41e-p09-c2r2__v141-a-M01-validation","page":9,"printed_page":null,"section":"Appendix B. Proof of Theorem 2","anchor_text":"Note that satisﬁes (21), and user can achieve the max- imum payoff by truthfully declaring for solvi","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-09.png","occurrence_role":"definition"},"source_text":"Note that \\(\\mathbf x(\\hat{\\mathbf I})\\) satisfies (21), and user \\(n\\) can achieve the maximum payoff by truthfully declaring \\(\\hat{\\mathbf I}_n=\\mathbf I_n\\) for solving (21). Since this optimal strategy does not depend on the demand information declared by other users, it confirms the result that for VCG mechanisms, truthful declaration is a dominant strategy."},{"evidence_id":"v141-b-g03-e01-vcg-declaration","location":{"location_id":"src-0fb1d9d41e-p08-c1r2__v141-a-M01-bidding","page":8,"printed_page":null,"section":"IV-C Communication Requirements of the VCG System","anchor_text":"Fig. 4. Payoff of the energy provider for the proposed VCG system, the system with price anticipatin","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"In the VCG system, each user is asked to declare its parameter \\omega and its feasible set of power consumption to the energy provider, and in return, the energy provider determines the payment and the allocated power of each user."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing","v141-a-M01-settlement","v141-a-M01-validation"],"extras":{"decision_anchor":"bidding.demand","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e019","quote":"If the VCG mechanism defined in (21) and (22) is used to select electricity payment values"},{"evidence_id":"v141-b-g02-e020","quote":"First, the payment of each user is structured such that regardless of other users’ strategies, the intended user cannot do better than truthfully declaring its demand information."}],[{"evidence_id":"v141-b-g01-E02","quote":"Our design requires that each user provides some information about its energy demand."},{"evidence_id":"v141-b-g01-E29","quote":"In the VCG class of mechanisms, each user is asked to specify its feasible set of power consumption and its utility function"},{"evidence_id":"v141-b-g01-E05","quote":"In our system model, each user reveals its demand information to the energy provider."}]],"C2_formalization":{"graph_sha256":"d7abc8ded251cc5cf71dc3c55163783a37d9a8666123b216d427087e497869ca","applicability":"formalized","reason":"C001 is formalized as the standard dominant-strategy payoff inequality for truthful demand declaration under the VCG allocation and payment rules (21)-(22); C003 transcribes the declared demand-information tuple from (16). C002 remains a procedural submission requirement and is not converted into an equation. The source-defined VCG allocation is referenced without adding any new graph node or edge. B evidence remains unreviewed; these evidence_ids are candidate support only.","bindings":[{"object_id":"v141-c-R001-X001","node_ids":["bidding.demand"],"edge_ids":["v141-c-R001-E001"],"rationale":"The declared demand-information tuple is the object chosen/submitted at the bidding.demand node; frozen edge E001 links the VCG payment construction at settlement.payment to this declaration behavior."},{"object_id":"v141-c-R001-T001","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"The true demand-information tuple is the user's fixed private type used in the declaration problem at bidding.demand; it is an input, not the settlement.payment choice."},{"object_id":"v141-c-R001-C001","node_ids":["settlement.payment","bidding.demand"],"edge_ids":["v141-c-R001-E001"],"rationale":"C001 formalizes the frozen implication from VCG payment construction at settlement.payment to truthful declaration at bidding.demand; edge E001 is exactly that implication."},{"object_id":"v141-c-R001-C002","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"The procedural submission requirement attaches to bidding.demand only; the frozen graph has no edge directly representing submission to the provider."},{"object_id":"v141-c-R001-C003","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"The declared tuple definition attaches to bidding.demand; no additional frozen edge is required for this definition."}],"revision_requests":[]}},"quarantined_references":[]}});
